def transform(grid):
    """Fill short (one- or two-cell) gaps between aligned marks with 2."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    values = [v for row in grid for v in row]
    background = max(set(values), key=values.count)
    # Repair only small gaps between consecutive marks on a row or column.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] != background]
        for a, b in zip(cols, cols[1:]):
            if 1 < b - a <= 3:
                for c in range(a + 1, b):
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] != background]
        for a, b in zip(rows, rows[1:]):
            if 1 < b - a <= 3:
                for r in range(a + 1, b):
                    out[r][c] = 2
    return out
